#include <iostream>
#include <string>
#include <stdexcept>
using namespace std;

int main() {
    string line;
    getline(cin, line);

    try {
        int n = stoi(line);
        cout << "数字是 " << n << " 喵" << endl;
    } catch (const invalid_argument& e) {
        cout << "这不是数字喵：" << e.what() << endl;
    }
    return 0;
}
